head.b:skin:
/* -----------------------------------------------
        Theme Name:  DualBoot 2.0
        Designer:    FRANCESCO_RUSSO
        Type:        Custom IT & Cybersecurity Portfolio
        Version:     2.0
----------------------------------------------- */


        :root {
            --bg-body: #f7f7f7; --bg-card: #ffffff; --text-main: #444444; 
            --text-title: #101010; --accent: #2A7F45; --border: rgba(0, 0, 0, 0.1);
        }
        body.dark-mode {
            --bg-body: #080808; --bg-card: #111111; --text-main: #888888; 
            --text-title: #ffffff; --accent: #4bffa5; --border: rgba(255, 255, 255, 0.1);
        }

        /* RESET */
        *, *::before, *::after { box-sizing: border-box; }

        /* FIX MOBILE: Sostituito width: 100vw con 100% per evitare overflow orizzontale */
        body { margin: 0; padding: 0; background: var(--bg-body); color: var(--text-main); font-family: 'Inter', -apple-system, sans-serif; transition: 0.3s; overflow-x: hidden; width: 100%; }

        /* GESTIONE LINGUE DOPPIE */
        .lang-it, .lang-en { display: none !important; }
        body.is-it .lang-it { display: inline-block !important; }
        body.is-en .lang-en { display: inline-block !important; }

		/* STILI LISTA CERTIFICAZIONI */
        .cert-list {
            font-size: 15px;
            line-height: 1.6;
            list-style-type: square;
            padding-left: 20px;
            margin-top: 5px;
        }
        .cert-list li {
            margin-bottom: 10px; 
        }
        .cert-id {
            font-family: monospace;
            font-size: 13px;
            color: var(--accent);
            display: inline-block;
            margin-left: 5px;
            opacity: 0.9;
        }
        h1, h2, h3, .post-title { color: var(--text-title) !important; margin: 0; }
        .post-title a { color: var(--text-title) !important; text-decoration: none !important; }
        a { color: var(--accent); text-decoration: none; }
		.post-body a, .custom-footer a { text-decoration: underline; text-underline-offset: 3px; }

        /* HEADER RESPONSIVE */
        .header-wrap { padding: 20px 5%; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--border); background: var(--bg-body); position: sticky; top: 0; z-index: 99; gap: 15px; }
        .logo-text a { display: flex; align-items: center; gap: 6px; color: var(--text-title) !important; font-size: 26px; font-weight: 800; letter-spacing: -0.5px; }
        .logo-it { background-color: var(--accent); color: #111; padding: 2px 6px; border-radius: 3px; }
        body.dark-mode .logo-it { color: #fff; }

        .unified-menu { display: flex; flex-wrap: wrap; align-items: center; gap: 24px; font-size: 15px; font-weight: 500; }
        .menu-item { color: var(--text-title); text-decoration: none; border: none; background: none; padding: 5px 0; cursor: pointer; transition: 0.2s; font-family: inherit; font-size: inherit; outline: none; }
        .menu-item:hover { opacity: 0.6; }

        /* TASTO DARK MODE SQUADRATO E COMPATTO */
        #t-btn { 
            background-color: #222 !important; 
            color: #fff !important; 
            border-radius: 3px !important; 
            padding: 5px 10px !important; 
            font-size: 11px !important; 
            font-weight: 600;
            letter-spacing: 0.5px;
            display: flex; 
            align-items: center; 
            border: 1px solid transparent;
        }
        body.dark-mode #t-btn { 
            background-color: #111 !important; 
            color: var(--accent) !important; 
            border: 1px solid var(--accent); 
        }

        /* HERO WRAP E LAYOUT */
        .hero-wrap { padding: 60px 5%; max-width: 1400px; margin: 0 auto; width: 100%; }
        .layout-home { display: flex; align-items: center; width: 100%; }
        .layout-home h1 { font-size: clamp(32px, 5vw, 48px); line-height: 1.1; margin: 5px 0; }
        .layout-about { display: none; align-items: flex-start; gap: 60px; width: 100%; }

        html.page-about .layout-home { display: none !important; }
        html.page-about .layout-about { display: flex !important; }
        html.page-about .main-container { display: none !important; }

        .chi-sono-text-col { flex: 1; min-width: 0; }
        .chi-sono-text-col h1 { font-size: clamp(32px, 5vw, 44px); font-weight: 800; line-height: 1.1; margin-bottom: 5px; letter-spacing: -1px; }
        .chi-sono-subtitle { font-family: monospace; font-size: 20px; color: var(--text-title); font-weight: 600; margin-bottom: 25px; display: block; }

        /* CONTENITORE FOTO + BARRA SOCIAL AFFIANCATI */
        .photo-and-social-wrapper { display: flex; gap: 15px; align-items: stretch; flex-shrink: 0; max-width: 100%; }

        .hero-photo-container { width: 100%; max-width: 420px; flex-shrink: 0; border: 4px solid #1c3b2b; background-color: #0f1a14; border-radius: 8px; display: flex; flex-direction: column; overflow: hidden; margin: 0; }
        body.dark-mode .hero-photo-container { border-color: var(--accent); }
        .photo-container-text { color: #379553; font-family: monospace; font-size: 18px; padding: 15px 20px; }
        body.dark-mode .photo-container-text { color: #4bffa5; }
        .photo-inner-img { width: 100%; padding: 0 15px 15px 15px; border-radius: 0 0 8px 8px; object-fit: cover; }

        /* NUOVA BARRA SOCIAL STATICA */
        .static-social-bar { background: var(--bg-card); border: 1px solid var(--border); border-radius: 8px; display: flex; flex-direction: column; padding: 15px 12px; gap: 20px; align-items: center; justify-content: flex-start; }
        .static-social-bar a { color: var(--text-main); transition: 0.3s; display: flex; }
        .static-social-bar a:hover { color: var(--accent); }

        /* MAIN CONTAINER E GRIGLIE */
        .main-container { 
            display: grid; 
            grid-template-columns: minmax(0, 1fr) 340px; 
            padding: 40px 5%; 
            gap: 50px; 
            max-width: 1400px; 
            margin: 0 auto; 
            width: 100%;
        }

        .post-outer, .sidebar-card { background: var(--bg-card); padding: 30px; border: 1px solid var(--border); margin-bottom: 30px; border-radius: 4px; overflow-wrap: break-word; word-wrap: break-word; }

        .cursor::after { content: '|'; animation: blink 0.8s infinite; color: var(--accent); }
        @keyframes blink { 0%, 100% {opacity: 1} 50% {opacity: 0} }

        .post-body pre { max-width: 100%; overflow-x: auto !important; background: #1a1a1a; padding: 15px; border-radius: 4px; }
        .post-body img { max-width: 100%; height: auto; }

        /* FOOTER PERSONALIZZATO */
        .custom-footer { 
            text-align: center; 
            padding: 25px 5%; 
            font-size: 12px; 
            color: var(--text-main); 
            border-top: 1px solid var(--border); 
            margin-top: 40px; 
            font-family: monospace; 
        }
        .custom-footer a { 
            color: var(--accent); 
            font-weight: bold; 
            text-decoration: none; 
            transition: 0.3s; 
        }
        .custom-footer a:hover { 
            opacity: 0.7; 
        }    

        /* RESPONSIVE MOBILE & TABLET COMPLETO E BLINDATO */
        @media (max-width: 992px) { 
            /* Fix principale: minmax(0, 1fr) impedisce alla griglia di esplodere se un elemento non va a capo */
            .main-container { grid-template-columns: minmax(0, 1fr); gap: 30px; padding: 30px 5%; } 

            .header-wrap { flex-direction: column; text-align: center; gap: 20px; }
            .unified-menu { justify-content: center; gap: 15px; } /* Menu leggermente più compatto per non sbordare */

            .layout-about { flex-direction: column; align-items: center; gap: 35px; }
            .chi-sono-text-col { padding-right: 0; width: 100%; }
            .chi-sono-text-col h1 { font-size: clamp(28px, 6vw, 36px); } /* Riduzione fluida del titolo della biografia */
            .chi-sono-subtitle { font-size: 16px; }

            .photo-and-social-wrapper { flex-direction: column; align-items: center; width: 100%; gap: 20px; }
            .static-social-bar { flex-direction: row; width: 100%; justify-content: center; flex-wrap: wrap; padding: 15px; }
        }

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
    var body = document.body;
    var btn = document.getElementById('t-btn');
    var langBtn = document.getElementById('lang-toggle');

    function updateTheme(isDark) {
        if (isDark) {
            body.classList.add('dark-mode');
            btn.innerHTML = "☀️ LIGHT";
        } else {
            body.classList.remove('dark-mode');
            btn.innerHTML = "🌙 DARK";
        }
    }

    btn.addEventListener('click', function() {
        var isDark = !body.classList.contains('dark-mode');
        updateTheme(isDark);
        localStorage.setItem('p-theme', isDark ? 'dark' : 'light');
    });

    if (localStorage.getItem('p-theme') === 'dark') updateTheme(true);

    function setLanguage(lang) {
        if (lang === 'en') {
            body.classList.replace('is-it', 'is-en');
            langBtn.innerHTML = "<strong>IT</strong>";
            localStorage.setItem('p-lang', 'en');
            document.querySelectorAll('.nav-link').forEach(el => {
               if(el.href.includes('/search/label/')) el.href = '/search/label/EN';
            });
        } else {
            body.classList.replace('is-en', 'is-it');
            langBtn.innerHTML = "<strong>EN</strong>";
            localStorage.setItem('p-lang', 'it');
            document.querySelectorAll('.nav-link').forEach(el => {
               if(el.href.includes('/search/label/')) el.href = '/search/label/IT';
            });
        }
    }

    langBtn.addEventListener('click', function(e) {
        e.preventDefault();
        var nextLang = body.classList.contains('is-it') ? 'en' : 'it';
        setLanguage(nextLang);
        if (!window.location.pathname.includes('.html')) {
            window.location.href = nextLang === 'en' ? '/search/label/EN' : '/search/label/IT';
        }
    });

    if (window.location.href.includes('/label/EN')) setLanguage('en');
    else if (localStorage.getItem('p-lang') === 'en') setLanguage('en');

    var words = ["> Cybersecurity", "> Windows Systems", "> Linux Systems", "> Automation", "> Data Recovery", "> DPIA", "> Business Impact Assessment", "> IT Risk Assessment", "> Digital Forensics DFIR", "> Project Management", "> Vulnerability Assessment"];
    var wIdx = 0, cIdx = 0, del = false;
    var target = document.getElementById('tw');
    function type() {
        if (!target) return;
        var cur = words[wIdx % words.length];
        target.innerText = cur.substring(0, cIdx);
        if (!del && cIdx === cur.length) { del = true; setTimeout(type, 2000); return; }
        if (del && cIdx === 0) { del = false; wIdx++; setTimeout(type, 500); return; }
        cIdx += del ? -1 : 1;
        setTimeout(type, del ? 50 : 100);
    }
    type();
});
//
